/// A key of a Curve filter: (t, v) in 0..1, eased towards the next one (curve: 0 to 5, 6 a Bézier by the handles, 100 a hold).
final class pxs_curve_key extends ffi.Struct {
  @ffi.Double()
  external double t;

  @ffi.Double()
  external double v;

  @ffi.Int32()
  external int curve;

  /// the Bézier handles; 0, 0: automatic
  @ffi.Double()
  external double in_dt;

  @ffi.Double()
  external double in_dv;

  @ffi.Double()
  external double out_dt;

  @ffi.Double()
  external double out_dv;

  static ffi.Pointer<pxs_curve_key> $allocate(
    ffi.Allocator $allocator, {
    required double t,
    required double v,
    required int curve,
    required double in_dt,
    required double in_dv,
    required double out_dt,
    required double out_dv,
  }) => $allocator<pxs_curve_key>()
    ..ref.t = t
    ..ref.v = v
    ..ref.curve = curve
    ..ref.in_dt = in_dt
    ..ref.in_dv = in_dv
    ..ref.out_dt = out_dt
    ..ref.out_dv = out_dv;
}

/// ---- DMX over the network (Art-Net, sACN) -------------------------------------------------------------------------------------
final class pxs_dmx_frame extends ffi.Struct {
  /// 1: sACN, 0: Art-Net
  @ffi.Int32()
  external int sacn;

  @ffi.Int32()
  external int universe;

  /// sACN
  @ffi.Int32()
  external int priority;

  @ffi.Int32()
  external int sequence;

  /// channels in the packet (1..512)
  @ffi.Int32()
  external int length;

  /// sACN
  @ffi.Int32()
  external int terminated;

  /// sACN: the sender's id
  @ffi.Array.multi([16])
  external ffi.Array<ffi.Uint8> cid;

  /// sACN: the source's name, NUL-terminated
  @ffi.Array.multi([64])
  external ffi.Array<ffi.Char> name;

  /// the levels
  @ffi.Array.multi([512])
  external ffi.Array<ffi.Uint8> values;
}

final class pxs_filter_chain extends ffi.Opaque {}

final class pxs_filter_setting extends ffi.Struct {
  /// static
  external ffi.Pointer<ffi.Char> name;

  /// " s", " /s" or ""
  external ffi.Pointer<ffi.Char> suffix;

  @ffi.Double()
  external double min;

  @ffi.Double()
  external double max;

  @ffi.Double()
  external double def;

  static ffi.Pointer<pxs_filter_setting> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> name,
    required ffi.Pointer<ffi.Char> suffix,
    required double min,
    required double max,
    required double def,
  }) => $allocator<pxs_filter_setting>()
    ..ref.name = name
    ..ref.suffix = suffix
    ..ref.min = min
    ..ref.max = max
    ..ref.def = def;
}

/// One stage of a chain, as the application keeps it
final class pxs_filter_stage extends ffi.Struct {
  @ffi.Int32()
  external int kind;

  @ffi.Int32()
  external int enabled;

  /// its settings
  @ffi.Double()
  external double a;

  @ffi.Double()
  external double b;

  @ffi.Double()
  external double c;

  @ffi.Double()
  external double d;

  /// Math
  @ffi.Int32()
  external int op;

  /// Curve: its keys (NULL or none: the value goes through)
  external ffi.Pointer<pxs_curve_key> curve;

  @ffi.Size()
  external int curve_count;

  static ffi.Pointer<pxs_filter_stage> $allocate(
    ffi.Allocator $allocator, {
    required int kind,
    required int enabled,
    required double a,
    required double b,
    required double c,
    required double d,
    required int op,
    required ffi.Pointer<pxs_curve_key> curve,
    required int curve_count,
  }) => $allocator<pxs_filter_stage>()
    ..ref.kind = kind
    ..ref.enabled = enabled
    ..ref.a = a
    ..ref.b = b
    ..ref.c = c
    ..ref.d = d
    ..ref.op = op
    ..ref.curve = curve
    ..ref.curve_count = curve_count;
}

/// Where a parameter's value lives: `get` fills `*out` (a string it points to must stay valid until the next call of `get` or `set` on
/// the same parameter) and returns 0; `set` takes the value written (already held within the parameter's limits) and returns 0.
typedef pxs_get_fn = ffi.Pointer<ffi.NativeFunction<pxs_get_fnFunction>>;
typedef pxs_get_fnFunction =
    ffi.Int Function(ffi.Pointer<ffi.Void> user, ffi.Pointer<pxs_value> out);
typedef Dartpxs_get_fnFunction =
    int Function(ffi.Pointer<ffi.Void> user, ffi.Pointer<pxs_value> out);

/// ---- values -------------------------------------------------------------------------------------------------------------------
enum pxs_kind {
  PXS_NIL(0),
  PXS_BOOL(1),
  PXS_INT32(2),
  PXS_INT64(3),
  PXS_FLOAT(4),
  PXS_DOUBLE(5),
  PXS_STRING(6),
  PXS_VEC2(7),
  PXS_VEC3(8),
  PXS_VEC4(9),
  PXS_BLOB(10);

  final int value;
  const pxs_kind(this.value);

  static pxs_kind fromValue(int value) => switch (value) {
    0 => PXS_NIL,
    1 => PXS_BOOL,
    2 => PXS_INT32,
    3 => PXS_INT64,
    4 => PXS_FLOAT,
    5 => PXS_DOUBLE,
    6 => PXS_STRING,
    7 => PXS_VEC2,
    8 => PXS_VEC3,
    9 => PXS_VEC4,
    10 => PXS_BLOB,
    _ => throw ArgumentError('Unknown value for pxs_kind: $value'),
  };
}

/// ---- MIDI channel messages ----------------------------------------------------------------------------------------------------
final class pxs_midi_message extends ffi.Struct {
  /// 0 control change, 1 note, 2 pitch bend, 3 program change
  @ffi.Int32()
  external int kind;

  /// 1..16
  @ffi.Int32()
  external int channel;

  /// the controller, the note, the program
  @ffi.Int32()
  external int number;

  /// 0..1 (a note off is 0)
  @ffi.Double()
  external double value;

  static ffi.Pointer<pxs_midi_message> $allocate(
    ffi.Allocator $allocator, {
    required int kind,
    required int channel,
    required int number,
    required double value,
  }) => $allocator<pxs_midi_message>()
    ..ref.kind = kind
    ..ref.channel = channel
    ..ref.number = number
    ..ref.value = value;
}

final class pxs_node extends ffi.Struct {
  /// "/kadran/controls/1/pad"
  external ffi.Pointer<ffi.Char> path;

  /// OSC type tags: "f", "ff", "fff", "s", "T"…
  external ffi.Pointer<ffi.Char> types;

  /// 1 read, 2 write, 3 both
  @ffi.Int32()
  external int access;

  /// may be NULL
  external ffi.Pointer<ffi.Char> description;

  /// OSCQuery UNIT of every argument ("distance.m"), or NULL
  external ffi.Pointer<ffi.Char> unit;

  /// the range of each argument: `range_count` entries (one per argument); NULL: none
  external ffi.Pointer<ffi.Double> min;

  external ffi.Pointer<ffi.Double> max;

  @ffi.Size()
  external int range_count;

  /// the keys a text node takes (RANGE VALS), or NULL
  external ffi.Pointer<ffi.Pointer<ffi.Char>> vals;

  @ffi.Size()
  external int vals_count;

  /// DEFAULT_VALUE, one per argument, or NULL: a reset writes these
  external ffi.Pointer<pxs_value> defaults;

  @ffi.Size()
  external int defaults_count;

  /// NULL: not readable
  external pxs_values_get_fn get;

  /// NULL: not writable
  external pxs_values_set_fn set;

  external ffi.Pointer<ffi.Void> user;

  static ffi.Pointer<pxs_node> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> path,
    required ffi.Pointer<ffi.Char> types,
    required int access,
    required ffi.Pointer<ffi.Char> description,
    required ffi.Pointer<ffi.Char> unit,
    required ffi.Pointer<ffi.Double> min,
    required ffi.Pointer<ffi.Double> max,
    required int range_count,
    required ffi.Pointer<ffi.Pointer<ffi.Char>> vals,
    required int vals_count,
    required ffi.Pointer<pxs_value> defaults,
    required int defaults_count,
    required pxs_values_get_fn get,
    required pxs_values_set_fn set,
    required ffi.Pointer<ffi.Void> user,
  }) => $allocator<pxs_node>()
    ..ref.path = path
    ..ref.types = types
    ..ref.access = access
    ..ref.description = description
    ..ref.unit = unit
    ..ref.min = min
    ..ref.max = max
    ..ref.range_count = range_count
    ..ref.vals = vals
    ..ref.vals_count = vals_count
    ..ref.defaults = defaults
    ..ref.defaults_count = defaults_count
    ..ref.get = get
    ..ref.set = set
    ..ref.user = user;
}

/// ---- OSC ----------------------------------------------------------------------------------------------------------------------
final class pxs_osc_packet extends ffi.Opaque {}

/// Everything the tree says (the feedback of a parameter, a signal fired): an OSC packet, to send.
typedef pxs_output_fn = ffi.Pointer<ffi.NativeFunction<pxs_output_fnFunction>>;
typedef pxs_output_fnFunction =
    ffi.Void Function(
      ffi.Pointer<ffi.Void> user,
      ffi.Pointer<ffi.Uint8> packet,
      ffi.Size size,
    );
typedef Dartpxs_output_fnFunction =
    void Function(
      ffi.Pointer<ffi.Void> user,
      ffi.Pointer<ffi.Uint8> packet,
      int size,
    );

enum pxs_param_type {
  PXS_PARAM_FLOAT(0),
  PXS_PARAM_INT(1),
  PXS_PARAM_BOOL(2),
  PXS_PARAM_CHOICE(3),
  PXS_PARAM_TEXT(4),
  PXS_PARAM_TRIGGER(5);

  final int value;
  const pxs_param_type(this.value);

  static pxs_param_type fromValue(int value) => switch (value) {
    0 => PXS_PARAM_FLOAT,
    1 => PXS_PARAM_INT,
    2 => PXS_PARAM_BOOL,
    3 => PXS_PARAM_CHOICE,
    4 => PXS_PARAM_TEXT,
    5 => PXS_PARAM_TRIGGER,
    _ => throw ArgumentError('Unknown value for pxs_param_type: $value'),
  };
}

/// How a control's numbers move, as pxs/core/physics/physics.h has it: mode 0 none (where the hand is), 1 Interpolate, 2 Mass-Spring.
final class pxs_physics extends ffi.Struct {
  @ffi.Int32()
  external int mode;

  @ffi.Double()
  external double friction;

  @ffi.Double()
  external double attraction;

  @ffi.Double()
  external double tension;

  @ffi.Double()
  external double wall;

  @ffi.Double()
  external double rate;

  static ffi.Pointer<pxs_physics> $allocate(
    ffi.Allocator $allocator, {
    required int mode,
    required double friction,
    required double attraction,
    required double tension,
    required double wall,
    required double rate,
  }) => $allocator<pxs_physics>()
    ..ref.mode = mode
    ..ref.friction = friction
    ..ref.attraction = attraction
    ..ref.tension = tension
    ..ref.wall = wall
    ..ref.rate = rate;
}

/// What an OSCQuery device answers to GET /, kept as a tree to browse and read. The sockets are the caller's (HTTP, WebSocket LISTEN, UDP): this
/// says what the answer and the values mean, with the same rule as the server's: a node with a TYPE or an ACCESS has a value, whether it holds
/// other nodes or not; one with neither is only a container. A reset is writing the node's DEFAULT_VALUE.
final class pxs_remote extends ffi.Opaque {}

typedef pxs_set_fn = ffi.Pointer<ffi.NativeFunction<pxs_set_fnFunction>>;
typedef pxs_set_fnFunction =
    ffi.Int Function(ffi.Pointer<ffi.Void> user, ffi.Pointer<pxs_value> in$);
typedef Dartpxs_set_fnFunction =
    int Function(ffi.Pointer<ffi.Void> user, ffi.Pointer<pxs_value> in$);

/// ---- general ------------------------------------------------------------------------------------------------------------------
enum pxs_status {
  PXS_OK(0),

  /// a NULL, a size or a number that cannot be
  PXS_ERR_ARGUMENT(-1),

  /// a packet or a text that is not what it should be, or beyond a limit
  PXS_ERR_MALFORMED(-2),

  /// no node at that address
  PXS_ERR_NOT_FOUND(-3),

  /// the node does not take that (locked, read only, a value that does not fit)
  PXS_ERR_REFUSED(-4),

  /// an exception was caught at the boundary: a bug, say it
  PXS_ERR_INTERNAL(-5);

  final int value;
  const pxs_status(this.value);

  static pxs_status fromValue(int value) => switch (value) {
    0 => PXS_OK,
    -1 => PXS_ERR_ARGUMENT,
    -2 => PXS_ERR_MALFORMED,
    -3 => PXS_ERR_NOT_FOUND,
    -4 => PXS_ERR_REFUSED,
    -5 => PXS_ERR_INTERNAL,
    _ => throw ArgumentError('Unknown value for pxs_status: $value'),
  };
}

/// ---- the address space --------------------------------------------------------------------------------------------------------
final class pxs_tree extends ffi.Opaque {}

/// A value of the address space. Which members mean something depends on `kind`: BOOL boolean; INT32 and INT64 integer; FLOAT and DOUBLE
/// number; VEC2/3/4 vec[0..n-1]; STRING and BLOB data and size (a string's size does not count its NUL). A value you give is read
/// during the call; a value you get points into what holds it.
final class pxs_value extends ffi.Struct {
  @ffi.Int32()
  external int kind;

  @ffi.Int32()
  external int boolean;

  @ffi.Int64()
  external int integer;

  @ffi.Double()
  external double number;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Float> vec;

  external ffi.Pointer<ffi.Uint8> data;

  @ffi.Size()
  external int size;
}

/// A node declared by hand, of any arguments: a point ("ff"), a colour ("fff"), a text with its keys, with a range per argument, a default, and the
/// way to read and write its values. `get` fills up to `capacity` values and says how many in `*count` (a string a value points to stays valid
/// until the next call of `get` or `set` of this node); `set` takes the values written (one per argument) and returns 0 when it took them. A
/// node with a value may hold other nodes (add them at their own paths).
typedef pxs_values_get_fn =
    ffi.Pointer<ffi.NativeFunction<pxs_values_get_fnFunction>>;
typedef pxs_values_get_fnFunction =
    ffi.Int Function(
      ffi.Pointer<ffi.Void> user,
      ffi.Pointer<pxs_value> out,
      ffi.Size capacity,
      ffi.Pointer<ffi.Size> count,
    );
typedef Dartpxs_values_get_fnFunction =
    int Function(
      ffi.Pointer<ffi.Void> user,
      ffi.Pointer<pxs_value> out,
      int capacity,
      ffi.Pointer<ffi.Size> count,
    );
typedef pxs_values_set_fn =
    ffi.Pointer<ffi.NativeFunction<pxs_values_set_fnFunction>>;
typedef pxs_values_set_fnFunction =
    ffi.Int Function(
      ffi.Pointer<ffi.Void> user,
      ffi.Pointer<pxs_value> in$,
      ffi.Size count,
    );
typedef Dartpxs_values_set_fnFunction =
    int Function(
      ffi.Pointer<ffi.Void> user,
      ffi.Pointer<pxs_value> in$,
      int count,
    );
